/*
 * Peças pequenas do chat: o avatar do usuário,
 * o ícone e o título do canal, o indicador de não lidas e a barra de
 * navegação (c-navbar) com os botões da gaveta.
 */
import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import classList from 'flarum/common/utils/classList';
import { openUserCard } from '../../../topic/components/UserCardPopover';
import chat from '../ChatStore';
import { channelTitle, chatUser, ct, displayName, emoji, isSelfDm, otherParticipants } from '../utils';
/** Avatar com o cartão de usuário no clique. */
export function ChatUserAvatar(userId, options = {}) {
  const user = chatUser(userId);
  return m("div", {
    className: classList('chat-user-avatar', options.size && `-${options.size}`)
  }, m("span", {
    className: "chat-user-avatar__container",
    onclick: options.interactive !== false && user ? e => cardFor(user, e) : undefined
  }, m(Avatar, {
    user: user,
    className: "avatar"
  })));
}
export function cardFor(user, event) {
  if (event.button !== 0 || event.metaKey || event.ctrlKey) return;
  event.preventDefault();
  event.stopPropagation();
  openUserCard(user, event.currentTarget);
}

/** O ícone do canal: o emoji, o ícone da tag na cor dela, ou os avatares da MD. */
export function ChannelIcon(channel) {
  if (channel.type === 'direct') {
    const others = otherParticipants(channel);
    if (channel.isGroup && others.length > 1) {
      return m("div", {
        className: "chat-channel-icon --users-count"
      }, m("span", null, channel.participantIds.length));
    }
    return m("div", {
      className: "chat-channel-icon --avatar"
    }, ChatUserAvatar(others[0], {
      interactive: false
    }));
  }
  if (channel.emoji) return m("div", {
    className: "chat-channel-icon --emoji"
  }, emoji(channel.emoji));
  return m("div", {
    className: "chat-channel-icon --icon",
    style: {
      color: channel.tag?.color || undefined
    }
  }, m(Icon, {
    name: channel.tag?.icon || 'fas fa-comment'
  }));
}
export function ChannelName(channel, unreadIndicator = false) {
  const urgent = chat.urgent(channel);
  const unread = chat.unread(channel);
  return m("div", {
    className: "chat-channel-name"
  }, m("span", {
    className: "chat-channel-name__label"
  }, channelTitle(channel), isSelfDm(channel) && m("span", {
    className: "chat-channel-name__you"
  }, " (", ct('you'), ")")), unreadIndicator && (urgent > 0 || unread > 0) && UnreadIndicator(urgent, unread > 0));
}
export function ChannelTitle(channel) {
  return m("div", {
    className: classList('chat-channel-title', channel.type === 'direct' ? 'is-dm' : 'is-category')
  }, ChannelIcon(channel), ChannelName(channel));
}

/** O ponto azul (há não lidas) ou o número verde (menções e MDs). */
export function UnreadIndicator(urgent, unread, className = 'chat-channel-unread-indicator') {
  if (urgent > 0) {
    return m("div", {
      className: `${className} -urgent`
    }, m("div", {
      className: `${className}__number`
    }, urgent > 99 ? '99+' : urgent));
  }
  return unread ? m("div", {
    className: className
  }) : null;
}
/**
 * A barra de cima da gaveta e da página cheia (c-navbar): voltar, o título e
 * os botões. Na gaveta, clicar no fundo da barra recolhe/expande, como lá.
 */
export function Navbar(attrs) {
  return m("div", {
    className: classList('c-navbar-container', {
      '-clickable': !!attrs.onclick
    }),
    onclick: attrs.onclick
  }, m("nav", {
    className: "c-navbar"
  }, attrs.back && m("button", {
    type: "button",
    className: "Button Button--icon Button--flat c-navbar__back-button",
    "aria-label": ct('channel_info.back_to_channel'),
    title: ct('channel_info.back_to_channel'),
    onclick: e => {
      e.stopPropagation();
      attrs.back();
    }
  }, m(Icon, {
    name: "fas fa-chevron-left"
  })), m("div", {
    className: "c-navbar__title"
  }, m("span", {
    className: "c-navbar__title-text"
  }, attrs.title), attrs.subTitle && m("div", {
    className: "c-navbar__sub-title"
  }, attrs.subTitle)), m("ul", {
    className: "c-navbar__actions"
  }, attrs.actions.map(action => m("li", {
    key: action.key
  }, m(Tooltip, {
    text: action.title
  }, m("button", {
    type: "button",
    className: classList('Button Button--icon Button--flat c-navbar__button', action.className, {
      active: action.active
    }),
    "aria-label": action.title,
    onclick: e => {
      e.stopPropagation();
      action.onclick(e);
    }
  }, m(Icon, {
    name: action.icon
  }), action.indicator)))))));
}

/** Os três botões da gaveta: recolher/expandir, tela cheia e fechar. */
export function drawerButtons(inDrawer) {
  if (!inDrawer) {
    return [];
  }
  return [{
    key: 'toggle',
    icon: chat.drawer.expanded ? 'fas fa-chevron-down' : 'fas fa-chevron-up',
    title: chat.drawer.expanded ? ct('collapse') : ct('expand'),
    className: 'c-navbar__toggle-drawer-button',
    onclick: () => chat.toggleExpand()
  }, {
    key: 'full',
    icon: 'fas fa-up-right-and-down-left-from-center',
    title: ct('open_full_page'),
    className: 'c-navbar__full-page-button',
    onclick: () => chat.openFullPage()
  }, {
    key: 'close',
    icon: 'fas fa-xmark',
    title: ct('close'),
    className: 'c-navbar__close-drawer-button',
    onclick: () => chat.closeDrawer()
  }];
}
export function userNames(ids) {
  return ids.map(id => displayName(id)).join(', ');
}
export function isPhone() {
  return app.screen() === 'phone';
}
flarum.reg.add('ramon-canela', 'forum/features/chat/components/bits', { ChatUserAvatar: ChatUserAvatar,cardFor: cardFor,ChannelIcon: ChannelIcon,ChannelName: ChannelName,ChannelTitle: ChannelTitle,UnreadIndicator: UnreadIndicator,Navbar: Navbar,drawerButtons: drawerButtons,userNames: userNames,isPhone: isPhone, });